#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Rect {
    long long x1, y1, x2, y2;
};

long long get_dist(const Rect& a, const Rect& b) {
    long long dx = 0;
    if (a.x1 > b.x2) {
        dx = a.x1 - b.x2;
    } else if (b.x1 > a.x2) {
        dx = b.x1 - a.x2;
    }

    long long dy = 0;
    if (a.y1 > b.y2) {
        dy = a.y1 - b.y2;
    } else if (b.y1 > a.y2) {
        dy = b.y1 - a.y2;
    }

    return dx + dy;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long xi, yi, xf, yf;
    if (!(cin >> xi >> yi >> xf >> yf)) return 0;

    int n;
    if (!(cin >> n)) return 0;

    vector<Rect> rects;
    rects.reserve(n + 2);

    rects.push_back({xi, yi, xi, yi});

    for (int i = 0; i < n; ++i) {
        long long x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        if (x1 > x2) swap(x1, x2);
        if (y1 > y2) swap(y1, y2);
        rects.push_back({x1, y1, x2, y2});
    }

    rects.push_back({xf, yf, xf, yf});

    int total_nodes = n + 2;
    const long long INF = 1e18;
    vector<long long> dist(total_nodes, INF);
    vector<bool> visited(total_nodes, false);

    dist[0] = 0;

    for (int i = 0; i < total_nodes; ++i) {
        int u = -1;
        long long min_d = INF;

        for (int j = 0; j < total_nodes; ++j) {
            if (!visited[j] && dist[j] < min_d) {
                min_d = dist[j];
                u = j;
            }
        }

        if (u == -1 || u == total_nodes - 1) {
            break;
        }

        visited[u] = true;

        for (int v = 0; v < total_nodes; ++v) {
            if (!visited[v]) {
                long long weight = get_dist(rects[u], rects[v]);
                if (dist[u] + weight < dist[v]) {
                    dist[v] = dist[u] + weight;
                }
            }
        }
    }

    cout << dist[total_nodes - 1] << "\n";

    return 0;
}
